CREATE TABLE payments (
    payment_id INT PRIMARY KEY,
    customer_id INT,
    amount DECIMAL(10,2)   -- NULL means amount not recorded
);

INSERT INTO payments VALUES
    (1, 100, 50.00),
    (2, 100, NULL),   -- amount missing
    (3, 200, 25.00);

-- SUM ignores the NULL row: 50.00 + 25.00 = 75.00
SELECT SUM(amount) AS total FROM payments;

-- Empty set returns NULL, not 0
SELECT SUM(amount) AS total FROM payments WHERE customer_id = 999;

-- COALESCE turns the empty-set NULL into 0
SELECT COALESCE(SUM(amount), 0) AS total
FROM payments
WHERE customer_id = 999;
